# Reviewed under AGENTS.md
"""Balanced bracket checking that ignores text inside double-quoted strings."""


def balanced(s: str) -> bool:
    """Return whether all brackets in *s* are balanced and properly nested.

    Brackets inside double-quoted strings are ignored. Inside a string, a
    backslash escapes the next character. An unterminated string makes *s*
    unbalanced.
    """
    stack: list[str] = []
    pairs = {')': '(', ']': '[', '}': '{'}
    in_string = False
    escaped = False

    for char in s:
        if in_string:
            if escaped:
                escaped = False
            elif char == '\\':
                escaped = True
            elif char == '"':
                in_string = False
            continue

        if char == '"':
            in_string = True
        elif char in '([{':
            stack.append(char)
        elif char in ')]}':
            if not stack or stack.pop() != pairs[char]:
                return False

    return not in_string and not stack
